<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';import * as echarts from 'echarts';const props=defineProps<{option:any;height?:string}>();const emit=defineEmits(['select']);const node=ref<HTMLElement>();let chart:echarts.ECharts;let observer:ResizeObserver;onMounted(()=>{chart=echarts.init(node.value!);chart.setOption(props.option||{});chart.on('click',(p)=>emit('select',p));observer=new ResizeObserver(()=>chart.resize());observer.observe(node.value!)});watch(()=>props.option,async v=>{await nextTick();chart?.setOption(v||{},true)},{deep:true});onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose()});defineExpose({focus:(id:string)=>{chart?.dispatchAction({type:'downplay'});chart?.dispatchAction({type:'highlight',name:id});chart?.dispatchAction({type:'showTip',name:id});}});
</script><template><div class="chart" ref="node" :style="{height:height||'var(--chart-height)'}"></div></template>